package cn.zj.zjmarket.infrastructure.adapter.port.payment;
import cn.bugstack.api.v2.*;
import cn.zj.zjmarket.domain.payment.adapter.port.ISettlementTransport;
import cn.zj.zjmarket.domain.payment.model.valobj.*;
import cn.zj.zjmarket.domain.order.adapter.repository.IOrderRepository;
import cn.zj.zjmarket.infrastructure.adapter.port.order.DubboTradePort;
import cn.zj.zjmarket.infrastructure.config.properties.*;
import cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec;
import cn.zj.zjmarket.infrastructure.gateway.rpc.RpcClientFactory;
import cn.zj.zjmarket.infrastructure.gateway.mq.*;
import cn.zj.zjmarket.domain.product.model.valobj.SyncBadMessage;
import cn.zj.zjmarket.types.exception.SyncTransportFailure;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.util.function.Supplier;
import org.apache.dubbo.config.ReferenceConfig;
import org.apache.dubbo.rpc.RpcContext;
import org.apache.rocketmq.client.producer.*;
import org.apache.rocketmq.client.consumer.*;
import org.apache.rocketmq.client.consumer.listener.*;
import org.apache.rocketmq.common.message.Message;
import org.apache.rocketmq.common.consumer.ConsumeFromWhere;
public final class RocketMqSettlementTransport implements ISettlementTransport,AutoCloseable {
 private final RpcSettings rpc;private final MqSettings mq;private final MqClientFactory factory;private final TradeMessageReader reader;private final IOrderRepository orders;private final ObjectMapper json=new ObjectMapper();private final ContractCodec codec=new ContractCodec();
 private final ReferenceConfig<IntegrationService> integration;private final ReferenceConfig<TradeService> trade;private final String topic,resultGroup,teamGroup;private DefaultMQProducer producer;private DefaultMQPushConsumer results,teams;
 public RocketMqSettlementTransport(RpcSettings rpc,MqSettings mq,RpcClientFactory rf,MqClientFactory mf,TradeMessageReader reader,IOrderRepository orders,String topic,String resultGroup,String teamGroup){this.rpc=rpc;this.mq=mq;factory=mf;this.reader=reader;this.orders=orders;this.topic=topic;this.resultGroup=resultGroup;this.teamGroup=teamGroup;integration=rf.reference(IntegrationService.class);trade=rf.reference(TradeService.class);integration.setCheck(false);trade.setCheck(false);integration.setTimeout(10000);trade.setTimeout(10000);}
 private DefaultMQPushConsumer subscribe(String group,String topic,String tags)throws Exception{var c=factory.consumer(group);c.setConsumeFromWhere(ConsumeFromWhere.CONSUME_FROM_FIRST_OFFSET);c.setConsumeMessageBatchMaxSize(1);c.setMaxReconsumeTimes(8);c.subscribe(topic,tags);c.registerMessageListener((MessageListenerConcurrently)(messages,context)->{try{for(var m:messages){reader.receive(new SyncBadMessage(m.getTopic(),m.getTags(),m.getUserProperty("keyId"),m.getUserProperty("signature"),m.getBody(),null),m.getKeys(),m.getUserProperty("source"),m.getUserProperty("channel"));}return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;}catch(Exception unavailable){return ConsumeConcurrentlyStatus.RECONSUME_LATER;}});try{c.start();return c;}catch(Exception e){c.shutdown();throw e;}}
 public synchronized void start()throws Exception{if(results==null)results=subscribe(resultGroup,mq.getResultTopic(),"EVENT_PROCESSING_RESULT");if(teams==null)teams=subscribe(teamGroup,mq.getTeamTopic(),"TEAM_COMPLETED || TEAM_FAILED || TEAM_RECONCILIATION_REQUIRED");}
 private synchronized DefaultMQProducer producer()throws Exception{if(producer==null){var p=factory.producer("B_TRADE_PRODUCER_"+UUID.randomUUID());try{p.start();producer=p;}catch(Exception e){p.shutdown();throw e;}}return producer;}
 private byte[] validate(TradeDelivery w)throws Exception{byte[] b=w.body().getBytes(StandardCharsets.UTF_8);if(b.length>256*1024||!ContractCodec.sha256(b).equals(w.hash()))throw fail("LOCAL_FACT_INVALID");var e=json.readTree(b);SyncResultReader.fields(e,"eventId,eventType,schemaVersion,producer,occurredAt,source,channel,correlationId,payload");var p=e.get("payload");String type=e.path("eventType").asText();if(type.equals("PAYMENT_SUCCEEDED"))SyncResultReader.fields(p,"userId,outTradeNo,paymentId,paidAmount,currency,paidAt");else if(type.equals("REFUND_STATUS_CHANGED")){SyncResultReader.fields(p,"userId,outTradeNo,paymentId,refundId,refundAmount,currency,refundStatus,refundVersion,occurredAt,paidAt,paidAmount");cn.zj.zjmarket.domain.order.model.valobj.ReservationEvidence.version(p.path("refundVersion").asText());if(!Set.of("PENDING","FAILED","SUCCEEDED").contains(p.path("refundStatus").asText()))throw fail("LOCAL_FACT_INVALID");}else throw fail("LOCAL_FACT_INVALID");if(!w.eventId().equals(e.path("eventId").asText())||!mq.getProducerId().equals(e.path("producer").asText())||!mq.getSource().equals(e.path("source").asText())||!mq.getChannel().equals(e.path("channel").asText())||!w.orderId().equals(p.path("outTradeNo").asText())||!w.paymentId().equals(p.path("paymentId").asText())||!w.userId().equals(p.path("userId").asText()))throw fail("LOCAL_FACT_INVALID");return b;}
 public void publish(TradeDelivery w){outside();try{byte[] body=validate(w);var m=new Message(topic,json.readTree(body).path("eventType").asText(),w.eventId(),body);m.putUserProperty("source",mq.getSource());m.putUserProperty("channel",mq.getChannel());m.putUserProperty("keyId",mq.getBKeyId());m.putUserProperty("signature",ContractCodec.hmac(mq.getBSecret(),topic+"\n"+ContractCodec.sha256(m.getBody())));if(producer().send(m,mq.getSendTimeoutMillis()).getSendStatus()!=SendStatus.SEND_OK)throw fail("SEND_OUTCOME_UNKNOWN");}catch(SyncTransportFailure e){throw e;}catch(Exception e){throw fail("TRADE_SEND_UNAVAILABLE");}}
 private <T> RpcResult<T> call(Class<?> type,String method,Object request,Supplier<RpcResult<T>> work)throws Exception{byte[] b=new byte[24];new java.security.SecureRandom().nextBytes(b);String time=Long.toString(System.currentTimeMillis()),nonce=Base64.getUrlEncoder().withoutPadding().encodeToString(b),id=UUID.randomUUID().toString();String signed=String.join("\n",rpc.getClientId(),rpc.getKeyId(),time,nonce,id,type.getName(),method,rpc.getVersion(),rpc.getGroup(),ContractCodec.sha256(codec.encode(request)));var a=Map.of("clientId",rpc.getClientId(),"keyId",rpc.getKeyId(),"timestamp",time,"nonce",nonce,"requestId",id,"signature",ContractCodec.hmac(rpc.getSecret(),signed));RpcResult<T> result;try{a.forEach((k,v)->RpcContext.getClientAttachment().setAttachment(k,v));result=work.get();}finally{RpcContext.getClientAttachment().clearAttachments();}if(result==null||!id.equals(result.getRequestId()))throw fail("UPSTREAM_RESPONSE_INVALID");return result;}
 private TradeReceipt receipt(TradeDelivery w,JsonNode payload)throws Exception{return receipt(w,payload,null);}
 private TradeReceipt receipt(TradeDelivery w,JsonNode payload,String authority)throws Exception{TradeMessageReader.validateResult(payload);String p=new String(codec.encode(payload),StandardCharsets.UTF_8),id="rpc-"+ContractCodec.sha256(codec.encode(Map.of("payload",payload,"authority",authority==null?"":authority))).substring(0,60);var e=new TreeMap<String,Object>();e.put("eventId",id);e.put("eventType","EVENT_PROCESSING_RESULT");e.put("schemaVersion",1);e.put("producer",mq.getAProducerId());e.put("occurredAt",payload.path("processedAt").asText());e.put("source",mq.getSource());e.put("channel",mq.getChannel());e.put("correlationId",w.eventId());e.put("payload",payload);byte[] bytes=codec.encode(e);return new TradeReceipt(mq.getAProducerId(),id,"EVENT_PROCESSING_RESULT",ContractCodec.sha256(bytes),new String(bytes,StandardCharsets.UTF_8),w.eventId(),authority);}
 public TradeReceipt query(TradeDelivery w){outside();try{validate(w);var q=new EventResultQueryRequest();q.setEventId(w.eventId());q.setSource(rpc.getSource());q.setChannel(rpc.getChannel());var response=call(IntegrationService.class,"queryEventResult",q,()->integration.get().queryEventResult(q));if("NOT_FOUND".equals(response.getCode())&&response.getData()==null)return null;if(!"0000".equals(response.getCode()))throw fail("TRADE_QUERY_UNAVAILABLE");var d=response.getData();if(d==null||!w.eventId().equals(d.getEventId())||!json.readTree(w.body()).path("eventType").asText().equals(d.getEventType()))throw fail("UPSTREAM_RESPONSE_INVALID");if("WAITING_DEPENDENCY".equals(d.getProcessingStatus())){if(d.getOutcome()!=null||d.getResult()!=null)throw fail("UPSTREAM_RESPONSE_INVALID");return null;}if(!"PROCESSED".equals(d.getProcessingStatus()))throw fail("UPSTREAM_RESPONSE_INVALID");var p=json.createObjectNode();p.put("originalEventId",d.getEventId());p.put("originalEventType",d.getEventType());p.put("outcome",d.getOutcome());p.put("code",d.getCode());p.put("info",d.getInfo());p.put("processedAt",d.getProcessedAt());p.set("result",json.valueToTree(d.getResult()));String authority=null;if(d.getEventType().equals("REFUND_STATUS_CHANGED")&&!"REJECTED".equals(d.getOutcome())&&Long.parseLong(p.path("result").path("refundVersion").asText())>Long.parseLong(json.readTree(w.body()).path("payload").path("refundVersion").asText())){var current=queryRefundTrade(w);if(current==null)return null;authority=new String(codec.encode(current),StandardCharsets.UTF_8);}return receipt(w,p,authority);}catch(SyncTransportFailure e){throw e;}catch(Exception e){throw fail("TRADE_QUERY_UNAVAILABLE");}}
 private Reservation queryRefundTrade(TradeDelivery w)throws Exception{var q=new TradeQueryRequest();q.setUserId(w.userId());q.setOutTradeNo(w.orderId());q.setSource(rpc.getSource());q.setChannel(rpc.getChannel());var response=call(TradeService.class,"query",q,()->trade.get().query(q));if("NOT_FOUND".equals(response.getCode())&&response.getData()==null)return null;if(!"0000".equals(response.getCode()))throw fail("TRADE_QUERY_UNAVAILABLE");var r=response.getData();DubboTradePort.map(r).validate(orders.byId(w.userId(),w.orderId()));return r;}
 private TradeReceipt refundTrade(TradeDelivery w)throws Exception{var r=queryRefundTrade(w);if(r==null||r.getRefund()==null||Long.parseLong(r.getRefund().getRefundVersion())<Long.parseLong(json.readTree(w.body()).path("payload").path("refundVersion").asText()))return null;var result=json.createObjectNode();result.put("outTradeNo",r.getOutTradeNo());result.put("refundId",r.getRefund().getRefundId());result.put("refundStatus",r.getRefund().getRefundStatus());result.put("refundVersion",r.getRefund().getRefundVersion());result.put("recordVersion",r.getRecordVersion());var p=json.createObjectNode();p.put("originalEventId",w.eventId());p.put("originalEventType","REFUND_STATUS_CHANGED");p.put("outcome","IGNORED");p.put("code","0000");p.put("info","Typed Trade query recovery");p.put("processedAt",r.getServerTime());p.set("result",result);return receipt(w,p,new String(codec.encode(r),StandardCharsets.UTF_8));}
 public TradeReceipt queryTrade(TradeDelivery w){outside();try{validate(w);if(json.readTree(w.body()).path("eventType").asText().equals("REFUND_STATUS_CHANGED"))return refundTrade(w);var q=new TradeQueryRequest();q.setUserId(w.userId());q.setOutTradeNo(w.orderId());q.setSource(rpc.getSource());q.setChannel(rpc.getChannel());var response=call(TradeService.class,"query",q,()->trade.get().query(q));if("NOT_FOUND".equals(response.getCode())&&response.getData()==null)return null;if(!"0000".equals(response.getCode()))throw fail("TRADE_QUERY_UNAVAILABLE");var r=response.getData();var order=orders.byId(w.userId(),w.orderId());DubboTradePort.map(r).validate(order);if(r.getPayment()==null)return null;if(!"PAID".equals(r.getOrderStatus()))throw fail("UPSTREAM_RESPONSE_INVALID");var result=json.createObjectNode();result.put("orderId",r.getOrderId());result.put("outTradeNo",r.getOutTradeNo());result.put("teamId",r.getTeamId());result.set("payment",json.valueToTree(r.getPayment()));result.put("orderStatus",r.getOrderStatus());result.put("teamStatus",r.getTeamStatus());result.put("recordVersion",r.getRecordVersion());result.put("teamVersion",r.getTeamVersion());var p=json.createObjectNode();p.put("originalEventId",w.eventId());p.put("originalEventType","PAYMENT_SUCCEEDED");p.put("outcome","IGNORED");p.put("code","0000");p.put("info","Trade query recovery");p.put("processedAt",r.getPayment().getPaidAt());p.set("result",result);return receipt(w,p);}catch(SyncTransportFailure e){throw e;}catch(Exception e){throw fail("TRADE_QUERY_UNAVAILABLE");}}
 private void outside(){if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Trade transport requires no ambient transaction");}
 private static SyncTransportFailure fail(String code){return new SyncTransportFailure(code,false);}
 public synchronized void close(){if(results!=null)results.shutdown();if(teams!=null)teams.shutdown();if(producer!=null)producer.shutdown();integration.destroy();trade.destroy();}
}
